assets/theme.css:
/* Forge — EcomStrait Liquid theme. Utilitarian: hard edges, condensed uppercase
   headings, heavy ink rules and a dense 5-up product grid. */
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;font-family:var(--font-body);color:var(--ink);background:var(--bg);line-height:1.55;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block;object-fit:cover}
a{color:inherit;text-decoration:none}
h1,h2,h3{font-family:var(--font-heading);line-height:1.05;margin:0;font-weight:700;text-transform:uppercase;letter-spacing:.01em}
.muted{color:var(--muted)}
.container{width:100%;max-width:1320px;margin:0 auto;padding:0 20px}
.section{padding:56px 0}
.section--narrow{max-width:720px;margin:0 auto}
.section-title{font-size:clamp(1.7rem,3.4vw,2.6rem)}
.section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:24px;padding-bottom:12px;border-bottom:3px solid var(--rule)}
.eyebrow{margin:0 0 14px;font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.22em;color:var(--brand)}
.link-more{font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.14em;white-space:nowrap}
.link-more:hover{color:var(--brand)}

/* Buttons — square, heavy, uppercase */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;border:2px solid var(--ink);cursor:pointer;font-family:var(--font-heading);font-weight:700;font-size:.86rem;text-transform:uppercase;letter-spacing:.1em;padding:.8rem 1.6rem;border-radius:var(--radius);transition:background-color .15s ease,color .15s ease}
.btn-lg{padding:1rem 2.2rem;font-size:.95rem}
.btn-primary{background:var(--brand);color:var(--ink);border-color:var(--ink)}
.btn-primary:hover{background:var(--ink);color:var(--bg)}
.btn-primary[disabled]{background:var(--wash);color:var(--muted);border-color:var(--line);cursor:not-allowed}
.btn-ghost{background:transparent;color:var(--ink)}
.btn-ghost:hover{background:var(--ink);color:var(--bg)}

/* Header */
.site-header{position:sticky;top:0;z-index:20;background:var(--bg);border-bottom:3px solid var(--rule)}
.site-header__inner{display:flex;align-items:center;justify-content:space-between;gap:24px;height:68px}
.site-header__name{font-family:var(--font-heading);font-weight:700;font-size:1.5rem;text-transform:uppercase;letter-spacing:.02em}
.site-nav{display:flex;gap:26px}
.site-nav__link{font-family:var(--font-heading);font-size:.84rem;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);padding:4px 0;border-bottom:3px solid transparent}
.site-nav__link:hover,.site-nav__link.is-active{color:var(--ink);border-color:var(--brand)}
.site-header__cart{font-family:var(--font-heading);font-size:.84rem;font-weight:700;text-transform:uppercase;letter-spacing:.1em;display:inline-flex;align-items:center;gap:8px}
.cart-count{display:inline-grid;place-items:center;min-width:22px;height:22px;padding:0 6px;background:var(--brand);color:var(--ink);font-size:.74rem;border-radius:var(--radius)}
@media (max-width:640px){.site-nav{display:none}}

/* Hero — hazard stripe, left aligned */
.hero{position:relative;background:var(--ink);color:var(--bg);background-size:cover;background-position:center}
.hero__stripes{position:absolute;top:0;left:0;right:0;height:10px;background:repeating-linear-gradient(45deg,var(--brand) 0 18px,var(--ink) 18px 36px)}
.hero__inner{padding:104px 20px 88px;max-width:920px;margin:0;text-align:left}
.hero__heading{font-size:clamp(2.3rem,6.2vw,4.6rem);max-width:16ch}
.hero__subheading{font-size:clamp(1rem,1.8vw,1.18rem);opacity:.78;margin:20px 0 32px;max-width:50ch}
.hero--image .hero__inner{padding:144px 20px 120px}
.hero .eyebrow{color:var(--brand)}
@media (max-width:640px){.hero__inner,.hero--image .hero__inner{padding:64px 20px 56px}}

/* Grids — dense */
.grid{display:grid;gap:2px;background:var(--line)}
.grid-products{grid-template-columns:repeat(2,1fr)}
.grid-collections{grid-template-columns:repeat(2,1fr)}
.grid-3{grid-template-columns:repeat(3,1fr);gap:20px;background:transparent}
@media (min-width:720px){.grid-products{grid-template-columns:repeat(4,1fr)}.grid-collections{grid-template-columns:repeat(3,1fr)}}
@media (min-width:1100px){.grid-products{grid-template-columns:repeat(5,1fr)}}
@media (max-width:640px){.grid-3{grid-template-columns:1fr}}

/* Product card — flat tiles separated by rules */
.product-card{display:flex;flex-direction:column;overflow:hidden;background:var(--bg);transition:background-color .15s ease}
.product-card:hover{background:var(--wash)}
.product-card__media{position:relative;aspect-ratio:1/1;background:var(--wash)}
.product-card__placeholder,.product-card--placeholder{aspect-ratio:1/1;background:repeating-linear-gradient(45deg,var(--wash) 0 10px,var(--bg) 10px 20px)}
.product-card__body{padding:12px 14px 16px;display:flex;flex-direction:column;gap:4px}
.product-card__meta{font-size:.64rem;font-weight:700;text-transform:uppercase;letter-spacing:.16em;color:var(--muted)}
.product-card__title{font-family:var(--font-heading);font-size:.95rem;font-weight:700;text-transform:uppercase;line-height:1.2}
.product-card__price{font-family:var(--font-heading);font-size:1.05rem;font-weight:700}
.badge{position:absolute;top:0;left:0;padding:5px 11px;font-size:.64rem;font-weight:700;text-transform:uppercase;letter-spacing:.14em}
.badge--soldout{background:var(--accent);color:#fff}
.price--sale .price__was{color:var(--muted);margin-right:8px;font-weight:400}
.price--sale .price__now{color:var(--accent)}

/* Product page */
.product{display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:start}
@media (max-width:820px){.product{grid-template-columns:1fr;gap:28px}}
.product__media img{border:3px solid var(--rule)}
.product__title{font-size:clamp(1.8rem,3.4vw,2.8rem)}
.product__price{font-family:var(--font-heading);font-size:1.7rem;font-weight:700;margin:12px 0 24px}
.product__options{display:flex;flex-wrap:wrap;gap:16px;margin-bottom:20px}
.product__option{display:flex;flex-direction:column;gap:6px;font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.16em;color:var(--muted)}
.product__option select{padding:.6rem .8rem;background:var(--bg);border:2px solid var(--ink);border-radius:var(--radius);color:var(--ink);font-family:var(--font-body);font-size:.92rem;font-weight:400;letter-spacing:0;text-transform:none}
.product__option select:focus-visible{outline:2px solid var(--brand);outline-offset:1px}
.product__media-placeholder{aspect-ratio:1/1;background:repeating-linear-gradient(45deg,var(--wash) 0 12px,var(--bg) 12px 24px)}

/* Spec table */
.spec{width:100%;border-collapse:collapse;margin-top:32px;font-size:.88rem}
.spec__caption{text-align:left;font-family:var(--font-heading);font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.18em;color:var(--muted);padding-bottom:10px;border-bottom:3px solid var(--rule)}
.spec th,.spec td{padding:11px 0;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
.spec th{width:38%;font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.14em;color:var(--muted)}
.product__description{margin-top:32px;padding-top:24px;border-top:3px solid var(--rule)}

/* Value props */
.value-prop{padding:22px 24px;background:var(--wash);border-left:6px solid var(--brand)}
.value-prop__title{font-size:1rem;margin-bottom:6px}

/* Cart */
.cart-line{display:grid;grid-template-columns:80px 1fr auto auto;gap:16px;align-items:center;padding:16px 0;border-bottom:1px solid var(--line)}
.cart-line__title{font-family:var(--font-heading);font-weight:700;text-transform:uppercase;font-size:.98rem}
.cart-line__qty{width:64px;padding:.5rem;background:var(--bg);border:2px solid var(--ink);border-radius:var(--radius);text-align:center;color:var(--ink);font-family:var(--font-body)}
.cart-footer{display:flex;flex-wrap:wrap;justify-content:space-between;gap:16px;align-items:center;padding-top:22px;border-top:3px solid var(--rule)}
.cart-subtotal{display:flex;align-items:baseline;gap:14px;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.16em;color:var(--muted)}
.cart-subtotal strong{font-family:var(--font-heading);font-size:1.7rem;letter-spacing:0;color:var(--ink);text-transform:none}
.cart-actions{display:flex;gap:12px}

/* Collections */
.collection-card{position:relative;display:block;overflow:hidden;background:var(--bg)}
.collection-card__title{position:absolute;left:0;bottom:0;background:var(--brand);color:var(--ink);padding:8px 14px;font-family:var(--font-heading);font-weight:700;text-transform:uppercase;letter-spacing:.08em;font-size:.88rem}
.collection-head{margin-bottom:24px;padding-bottom:12px;border-bottom:3px solid var(--rule)}
.collection-head__count{margin:10px 0 0;font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.16em}

/* Misc */
.rte a{color:var(--ink);text-decoration:underline;text-decoration-color:var(--brand);text-decoration-thickness:2px;text-underline-offset:3px}
.pagination{display:flex;gap:2px;justify-content:center;margin-top:36px;font-family:var(--font-heading);font-weight:700}
.pagination a,.pagination .is-current{padding:8px 16px;border:2px solid var(--ink)}
.pagination a:hover{background:var(--ink);color:var(--bg)}
.pagination .is-current{background:var(--brand)}
.search-form{display:flex;gap:2px;margin:18px 0 30px;max-width:620px}
.search-form input{flex:1;padding:.8rem 1rem;background:var(--bg);border:2px solid var(--ink);border-radius:var(--radius);color:var(--ink);font-family:var(--font-body)}
.search-form input::placeholder{color:var(--muted)}
.search-form input:focus-visible{outline:2px solid var(--brand);outline-offset:1px}
:focus-visible{outline:2px solid var(--brand);outline-offset:2px}

/* Footer */
.site-footer{margin-top:48px;border-top:6px solid var(--rule);padding:44px 0 24px;background:var(--wash)}
.site-footer__inner{display:flex;flex-wrap:wrap;justify-content:space-between;gap:26px}
.site-footer__name{font-family:var(--font-heading);font-weight:700;font-size:1.3rem;text-transform:uppercase;margin:0 0 6px}
.site-footer__nav{display:flex;flex-direction:column;gap:10px;font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.12em}
.site-footer__nav a:hover{color:var(--brand)}
.site-footer__legal{margin-top:28px;padding-top:18px;border-top:1px solid var(--line);font-size:.72rem;text-transform:uppercase;letter-spacing:.1em}

@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}

